begin
wwv_flow_imp_shared.create_flow_process(
 p_id=>wwv_flow_imp.id(37581996178343727855)
,p_process_sequence=>1
,p_process_point=>'AFTER_LOGIN'
,p_process_name=>'SET APPLICATION ITEMS'
,p_static_id=>'set-application-items'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'DECLARE',
'    v_page_id number := 2001;',
'BEGIN',
'    SELECT USER_ID, USER_NAME, EMAIL, ROLE_ID INTO :APP_USER_ID, :APP_USER_NAME, :APP_USER_EMAIL, :APP_ROLE_ID',
'    FROM XXPI_USERS',
'    WHERE UPPER(EMAIL) = UPPER(:APP_USER);',
'',
'    SELECT COUNT(*) INTO :APP_USER_CART_COUNT',
'    FROM XXPI_CART',
'    WHERE USER_ID = :APP_USER_ID;   ',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_version_scn=>'SH256:OJAJQMPZICIiiYTxz5Q_rTz7SkuJbJrYoFnnkz1jPuU'
