'    NVL(TO_CHAR(sum(JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].amount'')/ 100),''999G999G999G999G990D00''),''0'') as AMOUNT,',
'    count(*) as PAYMENT_COUNT,',
'    (''from ''|| count(*)|| '' captured payments'') as DESCRIPTION',
'from XXPI_PAYMENT_RESPONSE_HIST',
'where JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].id'') is not null',
'and JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].status'') = ''captured''',
'AND PAYMENT_TYPE_ID = 1',
'-- AND TRUNC(',
'--         DATE ''1970-01-01''',
'--         + ( JSON_VALUE(PAYMENT_RESPONSE_JSON, ''$.items[0].created_at'') / 86400 )',
'--       ) = TRUNC(SYSDATE)',
'UNION ALL',
'SELECT ',
'     ''Failed '' AS TEXT,',
'    NVL(TO_CHAR(sum(JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].amount'')/ 100),''999G999G999G999G990D00''),''0'') as AMOUNT,',
'    count(*) as PAYMENT_COUNT,',
'    (''from ''|| count(*) || '' failed payments'')',
'from XXPI_PAYMENT_RESPONSE_HIST',
'where JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].id'') is not null',
'and JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].status'') = ''failed''',
'AND PAYMENT_TYPE_ID = 1',
'-- AND TRUNC(',
'--         DATE ''1970-01-01''',
'--         + ( JSON_VALUE(PAYMENT_RESPONSE_JSON, ''$.items[0].created_at'') / 86400 )',
'--       ) = TRUNC(SYSDATE)',
'',
''))
