wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(37987874701903022901)
,p_name=>'RazorPay Orders'
,p_static_id=>'razorpay-orders'
,p_parent_plug_id=>wwv_flow_imp.id(37339637196219973941)
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_include_in_reg_disp_sel_yn=>'Y'
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:i-h480:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlightOff:t-Report--horizontalBorders'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.id''), ''N/A'')AS ORDER_ID,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.amount'') / 100, 0)AS AMOUNT,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.amount_paid'') / 100, 0)AS AMOUNT_PAID,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.amount_due'') / 100, 0)AS AMOUNT_DUE,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.currency''), ''N/A'')AS CURRENCY,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.receipt''), ''N/A'')AS RECEIPT,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.status''), ''N/A'')AS STATUS,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.attempts''), ''N/A'')AS ATTEMPTS,',
'    DATE ''1970-01-01''',
'      + ( json_value(R_ORDER_RESPONSE_JSON, ''$.created_at'') / 86400 )',
'        AS CREATED_DATETIME',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE (json_value(R_ORDER_RESPONSE_JSON, ''$.id'')) IS NOT NULL',
'AND PAYMENT_TYPE_ID = 1',
'-- STATUS FILTER',
'AND (:P2_RAZORPAY_ORDER_STATUS IS NULL',
'    OR (json_value(R_ORDER_RESPONSE_JSON, ''$.status'')) = :P2_RAZORPAY_ORDER_STATUS)',
'',
'-- PAYMENT ID FILTER',
'AND (trim(:P2_RAZORPAY_ORDER_ID) IS NULL',
'    OR (trim(json_value(R_ORDER_RESPONSE_JSON, ''$.id''))) = trim(:P2_RAZORPAY_ORDER_ID))',
'',
'-- PERIOD FILTER',
'',
'AND (:P2_RAZORPAY_ORDER_PERIOD IS NULL',
'      OR( :P2_RAZORPAY_ORDER_PERIOD = ''1TODAY''',
'        AND TRUNC(',
'              DATE ''1970-01-01''',
'              + ( JSON_VALUE(R_ORDER_RESPONSE_JSON,''$.created_at'') / 86400 )',
'            ) = TRUNC(SYSDATE)',
'      )',
'   OR ',
'      ( :P2_RAZORPAY_ORDER_PERIOD = ''2LAST_7_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(R_ORDER_RESPONSE_JSON,''$.created_at'') / 86400 )',
'            >= TRUNC(SYSDATE) - 6',
'      )',
'   OR ',
'      ( :P2_RAZORPAY_ORDER_PERIOD = ''3LAST_30_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(R_ORDER_RESPONSE_JSON,''$.created_at'') / 86400 )',
'            >= TRUNC(SYSDATE) - 29',
'      )',
'   OR ',
'      ( :P2_RAZORPAY_ORDER_PERIOD = ''4LAST_365_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(R_ORDER_RESPONSE_JSON,''$.created_at'') / 86400 )',
'            >= TRUNC(SYSDATE) - 364',
'      )',
'    )',
'ORDER BY CREATED_DATETIME DESC;',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2_RAZORPAY_ORDER_PERIOD,P2_RAZORPAY_ORDER_STATUS,P2_RAZORPAY_ORDER_ID'
