wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(37339636158329973931)
,p_name=>'RazorPay Payments'
,p_static_id=>'razorpay-payments'
,p_parent_plug_id=>wwv_flow_imp.id(37339635017062973920)
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:i-h480:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlightOff:t-Report--horizontalBorders'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].id''),''N/A'') AS PAYMENT_ID,',
'    NVL(USER_NAME, ''N/A'') AS USER_NAME,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].email''),''N/A'') AS EMAIL,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].contact''),''N/A'') AS PHONE,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].amount'') / 100, 0) AS AMOUNT,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].status''),''N/A'') AS PAYMENT_STATUS,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].method''),''N/A'') AS PAYMENT_METHOD,',
'',
'    DATE ''1970-01-01''',
'      + ( json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].created_at'') / 86400 )',
'        AS CREATED_DATETIME,',
'',
'    CASE',
'        WHEN (json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].status'')) = ''captured'' THEN ''fa-check''',
'        WHEN (json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].status'')) = ''failed'' THEN ''fa-times''',
'    ELSE ''fa-info-circle''',
'    END AS STATUS_ICONS',
'',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE PAYMENT_TYPE_ID = 1 ',
'AND json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].id'') IS NOT NULL',
'',
'-- STATUS FILTER',
'AND (:P2_RAZORPAY_PAYMENT_STATUS IS NULL',
'    OR (json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].status'')) = :P2_RAZORPAY_PAYMENT_STATUS)',
'',
'-- METHOD FILTER',
'AND (:P2_RAZORPAY_PAYMENT_METHOD IS NULL',
'    OR (json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].method'')) = :P2_RAZORPAY_PAYMENT_METHOD)',
'',
'-- PAYMENT ID FILTER',
'AND (trim(:P2_RAZORPAY_PAYMENT_ID) IS NULL',
'    OR (trim(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].id''))) = trim(:P2_RAZORPAY_PAYMENT_ID))',
'',
'-- PERIOD FILTER',
'',
'AND (:P2_RAZORPAY_PAYMENT_PERIOD IS NULL',
'      OR( :P2_RAZORPAY_PAYMENT_PERIOD = ''1TODAY''',
'        AND TRUNC(',
'              DATE ''1970-01-01''',
'              + ( JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].created_at'') / 86400 )',
'            ) = TRUNC(SYSDATE)',
'      )',
'   OR ',
'      ( :P2_RAZORPAY_PAYMENT_PERIOD = ''2LAST_7_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].created_at'') / 86400 )',
'            >= TRUNC(SYSDATE) - 6',
'      )',
'   OR ',
'      ( :P2_RAZORPAY_PAYMENT_PERIOD = ''3LAST_30_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].created_at'') / 86400 )',
'            >= TRUNC(SYSDATE) - 29',
'      )',
'   OR ',
'      ( :P2_RAZORPAY_PAYMENT_PERIOD = ''4LAST_365_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.items[0].created_at'') / 86400 )',
'            >= TRUNC(SYSDATE) - 364',
'      )',
'    )',
'ORDER BY CREATED_DATETIME DESC;',
''))
,p_ajax_enabled=>'Y'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_options=>'DERIVED_REPORT_COLUMNS'
