wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(37987877122757022925)
,p_name=>'Stripe Payments'
,p_static_id=>'stripe-payments'
,p_parent_plug_id=>wwv_flow_imp.id(37987876039696022914)
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--altRowsDefault:t-Report--rowHighlight'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.amount'') / 100, 0)AS AMOUNT,',
'    NVL(UPPER(json_value(PAYMENT_RESPONSE_JSON, ''$.currency'')), ''N/A'')AS CURRENCY,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.status''), ''N/A'')AS STATUS,',
'',
'    CASE',
'        WHEN json_value(PAYMENT_RESPONSE_JSON, ''$.status'') = ''requires_source'' THEN ''Incompleted''',
'        ELSE INITCAP(json_value(PAYMENT_RESPONSE_JSON, ''$.status''))',
'    END AS PAYMENT_STATUS,',
'    CASE',
'        WHEN json_value(PAYMENT_RESPONSE_JSON, ''$.status'') = ''requires_source'' THEN ''fa-clock-o''',
'        WHEN json_value(PAYMENT_RESPONSE_JSON, ''$.status'') = ''succeeded'' THEN ''fa-check''',
'        ELSE ''fa-times''',
'    END AS STATUS_ICON,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.id''), ''N/A'')AS PAYMENT_ID,',
'    NVL(INITCAP(json_value(PAYMENT_RESPONSE_JSON, ''$.payment_method_types[*]'')), ''-'')AS METHOD,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.charges.data[0].billing_details.email''), ''-'')AS CUSTOMER_EMAIL,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.charges.data[0].billing_details.name''), ''-'')AS CUSTOMER_NAME,',
'    DATE ''1970-01-01''',
'      + ( json_value(PAYMENT_RESPONSE_JSON, ''$.created'') / 86400 )',
'        AS CREATED_DATETIME',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE (json_value(PAYMENT_RESPONSE_JSON, ''$.id'')) IS NOT NULL',
'AND PAYMENT_TYPE_ID = 2',
'',
'-- Payment Id',
'AND (trim(:P2_STRIPE_PAYMENT_ID) IS NULL',
'    OR (trim(json_value(PAYMENT_RESPONSE_JSON, ''$.id''))) = trim(:P2_STRIPE_PAYMENT_ID))',
'',
'-- Method',
'AND (trim(:P2_STRIPE_PAYMENT_METHOD) IS NULL',
'    OR (trim(json_value(PAYMENT_RESPONSE_JSON, ''$.payment_method_types[*]''))) = trim(:P2_STRIPE_PAYMENT_METHOD))',
'',
'-- status',
'AND (trim(:P2_STRIPE_PAYMENT_STATUS) IS NULL',
'    OR (trim(json_value(PAYMENT_RESPONSE_JSON, ''$.status''))) = trim(:P2_STRIPE_PAYMENT_STATUS))',
'',
'-- PERIOD FILTER',
'',
'AND (:P2_STRIPE_PAYMENT_PERIOD IS NULL',
'      OR( :P2_STRIPE_PAYMENT_PERIOD = ''1TODAY''',
'        AND TRUNC(',
'              DATE ''1970-01-01''',
'              + ( JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.created'') / 86400 )',
'            ) = TRUNC(SYSDATE)',
'      )',
'   OR ',
'      ( :P2_STRIPE_PAYMENT_PERIOD = ''2LAST_7_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.created'') / 86400 )',
'            >= TRUNC(SYSDATE) - 6',
'      )',
'   OR ',
'      ( :P2_STRIPE_PAYMENT_PERIOD = ''3LAST_30_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.created'') / 86400 )',
'            >= TRUNC(SYSDATE) - 29',
'      )',
'   OR ',
'      ( :P2_STRIPE_PAYMENT_PERIOD = ''4LAST_365_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(PAYMENT_RESPONSE_JSON,''$.created'') / 86400 )',
'            >= TRUNC(SYSDATE) - 364',
'      )',
'    )',
'    ',
'ORDER BY CREATED_DATETIME DESC',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2_STRIPE_SESSION_STATUS,,P2_STRIPE_PAYMENT_METHOD,P2_STRIPE_PAYMENT_ID,P2_STRIPE_PAYMENT_PERIOD'
,p_lazy_loading=>false
,p_query_row_template=>2540130677583398057
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260914112517Z')
,p_updated_on=>wwv_flow_imp.dz('20260918084814Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
