wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(37987879327791022947)
,p_name=>'Stripe Sessions'
,p_static_id=>'stripe-sessions'
,p_parent_plug_id=>wwv_flow_imp.id(37987878264868022936)
,p_template=>4073835273271169698
,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-Region--noPadding:t-Region--removeHeader js-removeLandmark:t-Region--noUI:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-Report--stretch:t-Report--altRowsDefault:t-Report--rowHighlight:t-Report--horizontalBorders'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    NVL(json_value(S_SESSION_RESPONSE_JSON, ''$.id''), ''-'')AS SESSION_ID,',
'    NVL(json_value(S_SESSION_RESPONSE_JSON, ''$.amount_total'') / 100, 0)AS AMOUNT,',
'    NVL(UPPER(json_value(S_SESSION_RESPONSE_JSON, ''$.currency'')), ''-'')AS CURRENCY,',
'    NVL(INITCAP(json_value(S_SESSION_RESPONSE_JSON, ''$.payment_status'')), ''-'')AS SESSION_PAYMENT_STATUS,',
'    NVL(INITCAP(json_value(S_SESSION_RESPONSE_JSON, ''$.status'')), ''-'')AS SESSION_STATUS,',
'    NVL(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.email''), ''-'')AS CUSTOMER_EMAIL,',
'    NVL(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.name''), ''-'')AS CUSTOMER_NAME,',
'',
'    DATE ''1970-01-01''',
'      + ( json_value(S_SESSION_RESPONSE_JSON, ''$.created'') / 86400 )',
'        AS CREATED_DATETIME',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE (json_value(S_SESSION_RESPONSE_JSON, ''$.id'')) IS NOT NULL',
'AND PAYMENT_TYPE_ID = 2',
'',
'-- Payment Id',
'AND (trim(:P2_STRIPE_SESSION_ID) IS NULL',
'    OR (trim(json_value(S_SESSION_RESPONSE_JSON, ''$.id''))) = trim(:P2_STRIPE_SESSION_ID))',
'',
'-- Session status',
'AND (trim(:P2_STRIPE_SESSION_STATUS) IS NULL',
'    OR (trim(json_value(S_SESSION_RESPONSE_JSON, ''$.status''))) = trim(:P2_STRIPE_SESSION_STATUS))',
'',
'-- Session Payment status',
'AND (trim(:P2_STRIPE_SESSION_PAYMENT_STATUS) IS NULL',
'    OR (trim(json_value(S_SESSION_RESPONSE_JSON, ''$.payment_status''))) = trim(:P2_STRIPE_SESSION_PAYMENT_STATUS))',
'',
'-- PERIOD FILTER',
'',
'AND (:P2_STRIPE_SESSION_PERIOD IS NULL',
'      OR( :P2_STRIPE_SESSION_PERIOD = ''1TODAY''',
'        AND TRUNC(',
'              DATE ''1970-01-01''',
'              + ( JSON_VALUE(S_SESSION_RESPONSE_JSON,''$.created'') / 86400 )',
'            ) = TRUNC(SYSDATE)',
'      )',
'   OR ',
'      ( :P2_STRIPE_SESSION_PERIOD = ''2LAST_7_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(S_SESSION_RESPONSE_JSON,''$.created'') / 86400 )',
'            >= TRUNC(SYSDATE) - 6',
'      )',
'   OR ',
'      ( :P2_STRIPE_SESSION_PERIOD = ''3LAST_30_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(S_SESSION_RESPONSE_JSON,''$.created'') / 86400 )',
'            >= TRUNC(SYSDATE) - 29',
'      )',
'   OR ',
'      ( :P2_STRIPE_SESSION_PERIOD = ''4LAST_365_DAYS''',
'        AND DATE ''1970-01-01''',
'            + ( JSON_VALUE(S_SESSION_RESPONSE_JSON,''$.created'') / 86400 )',
'            >= TRUNC(SYSDATE) - 364',
'      )',
'    )',
'ORDER BY CREATED_DATETIME DESC',
''))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P2_STRIPE_SESSION_PERIOD,P2_STRIPE_SESSION_STATUS,P2_STRIPE_SESSION_PAYMENT_STATUS,P2_STRIPE_SESSION_ID'
