  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    l_count number;',
    'BEGIN',
    '    SELECT COUNT(*) INTO l_count',
    '    FROM XXPI_CART',
    '    WHERE USER_ID = :APP_USER_ID',
    '    AND PRODUCT_ID = :P18_PRODUCT_ID;',
    '',
    '    IF l_count = 0 THEN',
    '        INSERT INTO XXPI_CART(',
    '            USER_ID,',
    '            PRODUCT_ID,',
    '            QTY',
    '        ) VALUES(',
    '            :APP_USER_ID,',
    '            :P18_PRODUCT_ID,',
    '            1',
    '        );',
    '',
    '    END IF;',
    '',
    '    SELECT COUNT(*) INTO :APP_USER_CART_COUNT',
    '    FROM XXPI_CART',
    '    WHERE USER_ID = :APP_USER_ID;',
    'END;',
    '    ')),
  'show_processing', 'N')).to_clob
