,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'-- SELECT ',
'--     O.ORDER_ID AS ORDER_ID,',
'--     O.TOTAL_AMOUNT AS TOTAL_AMOUNT,',
'--     O.CREATED_AT AS ORDER_DATE,',
'--     CASE',
'--         WHEN O.PAYMENT_STATUS = ''paid'' OR O.PAYMENT_STATUS = ''captured'' OR O.PAYMENT_STATUS = ''succeeded'' THEN ''Completed''',
'--         ELSE ''Fail''',
'--     END AS ORDER_STATUS',
'-- FROM XXPI_ORDERS O',
'-- WHERE O.USER_ID = :APP_USER_ID',
'',
'SELECT ',
'    O.ORDER_ID AS ORDER_ID,',
'    O.TOTAL_AMOUNT AS TOTAL_AMOUNT,',
'    O.CREATED_AT AS ORDER_DATE,',
'    CASE',
'        WHEN O.PAYMENT_STATUS = ''paid'' OR O.PAYMENT_STATUS = ''captured'' OR O.PAYMENT_STATUS = ''succeeded'' THEN ''Completed''',
'        ELSE ''Fail''',
'    END AS ORDER_STATUS,',
'    U.USER_IMAGE AS USER_IMAGE',
'FROM XXPI_ORDERS O',
'JOIN XXPI_USERS U',
'ON O.USER_ID = U.USER_ID',
'WHERE O.USER_ID = :APP_USER_ID'))
,p_template_component_type=>'REPORT'
