 p_id=>wwv_flow_imp.id(38297060711850534833)
,p_plug_name=>'Order Summary'
,p_static_id=>'order-summary'
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc:t-CardsRegion--styleC'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>30
,p_plug_new_grid_row=>false
,p_plug_grid_column_span=>4
,p_plug_item_display_point=>'BELOW'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    SUM(C.QTY) AS ITEMS,',
'',
'    TO_CHAR(',
'      ROUND(SUM(P.PRICE * C.QTY), 2),',
'      ''999G999G999G999G999G999G990D00''',
'    ) AS SUBTOTAL,',
'',
'    TO_CHAR(',
'      ROUND(SUM(P.PRICE * C.QTY) * 0.10, 2),',
'      ''999G999G999G999G999G999G990D00''',
'    ) AS TAX,',
'',
'    TO_CHAR(',
'      ROUND(SUM(P.PRICE * C.QTY) * 1.10, 2),',
'      ''999G999G999G999G999G999G990D00''',
'    ) AS TOTAL',
'',
'FROM XXPI_CART C',
'JOIN XXPI_PRODUCTS P',
'  ON P.PRODUCT_ID = C.PRODUCT_ID',
'WHERE C.USER_ID = :APP_USER_ID;',
''))
