  'language', 'PLSQL',
  'plsql_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'DECLARE',
    '    l_count number;',
    'BEGIN',
    '    SELECT COUNT(*) INTO l_count',
    '    FROM XXPI_CART',
    '    WHERE USER_ID = :APP_USER_ID',
    '    AND PRODUCT_ID = :P21_PRODUCT_ID;',
    '',
    '    IF l_count > 0 THEN',
    '        DELETE FROM XXPI_CART',
    '        WHERE USER_ID = :APP_USER_ID',
    '        AND PRODUCT_ID = :P21_PRODUCT_ID;',
    '    END IF;',
    '',
    '    SELECT COUNT(*) INTO :APP_USER_CART_COUNT',
    '    FROM XXPI_CART',
    '    WHERE USER_ID = :APP_USER_ID;',
    'END;',
    '    ')),
  'show_processing', 'N')).to_clob
