wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(38307466542801106517)
,p_plug_name=>'Price Details'
,p_static_id=>'price-details'
,p_parent_plug_id=>wwv_flow_imp.id(38297062197732534847)
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>30
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    SUM(C.QTY) AS ITEMS,',
'',
'    TO_CHAR(',
'      ROUND(SUM(P.PRICE * C.QTY), 2),',
'      ''999G999G999G999G999G999G990D00''',
'    ) AS SUBTOTAL,',
'',
'    TO_CHAR(',
'      ROUND(SUM(P.PRICE * C.QTY) * 0.10, 2),',
'      ''999G999G999G999G999G999G990D00''',
'    ) AS TAX,',
'',
'    TO_CHAR(',
'      ROUND(SUM(P.PRICE * C.QTY) * 1.10, 2),',
'      ''999G999G999G999G999G999G990D00''',
'    ) AS TOTAL',
'',
'FROM XXPI_CART C',
'JOIN XXPI_PRODUCTS P',
'  ON P.PRODUCT_ID = C.PRODUCT_ID',
'WHERE C.USER_ID = :APP_USER_ID;',
''))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20260915073705Z')
,p_updated_on=>wwv_flow_imp.dz('20260915073706Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
