    '    email: email,',
    '    contact: mobile',
    '  },',
    '',
    '  theme: {',
    '    color: "#F37254"',
    '  },',
    '',
    '  /* ===== USER CLOSES PAYMENT POPUP ===== */',
    '  modal: {',
    '    ondismiss: function () {',
    '',
    '      var targetPage = 11;',
    '',
    '      var url =',
    '        "f?p=&APP_ID.:" +',
    '        targetPage +',
    '        ":&APP_SESSION.::NO::" +',
    '        "P23_ORDER_ID:" +',
    '        encodeURIComponent(ordid);',
    '',
    '      apex.navigation.redirect(url);',
    '    }',
    '  }',
    '};',
    '',
    '/* ===== CREATE RAZORPAY INSTANCE ===== */',
    'var rzp1 = new Razorpay(options);',
    '',
    '/* ===== PAYMENT FAILED ===== */',
    'rzp1.on(''payment.failed'', function (response) {',
    '',
    '  var targetPage = 11;',
    '',
    '  var url =',
