    '    targetPage +',
    '    ":&APP_SESSION.::NO::" +',
    '    "P11_ORDER_ID:" +',
    '    encodeURIComponent(ordid);',
    '',
    '  apex.navigation.redirect(url);',
    '});',
    '',
    '/* ===== OPEN PAYMENT POPUP ===== */',
    'rzp1.open();',
    '')))).to_clob
