,p_process_name=>'SAVE_RAZORPAY_SUCCESS'
,p_static_id=>'save-razorpay-success'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'  XXPI_PAYMENT_RESPONSE.RP_SAVE_RAZORPAY_SUCCESS(',
'    p_payment_id => apex_application.g_x01,',
'    p_order_id   => apex_application.g_x02,',
