,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Set Page Item Value'
,p_static_id=>'set-page-item-value'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'BEGIN',
'    SELECT USER_NAME, EMAIL, PHONE_NUMBER ',
'    INTO :P22_USER_NAME, :P22_USER_EMAIL, :P22_USER_MOBILE',
'    FROM XXPI_USERS',
'    WHERE USER_ID = :APP_USER_ID;',
'',
'    SELECT ROUND(SUM(P.PRICE * C.QTY) * 1.10, 2) INTO :P22_TOTAL_AMOUNT',
'    FROM XXPI_CART C',
'    JOIN XXPI_PRODUCTS P',
'    ON P.PRODUCT_ID = C.PRODUCT_ID',
'    WHERE C.USER_ID = :APP_USER_ID;',
'END;'))
,p_process_clob_language=>'PLSQL'
,p_internal_uid=>38297061523786534841
,p_created_on=>wwv_flow_imp.dz('20260915073706Z')
