wwv_flow_imp_page.create_report_region(
 p_id=>wwv_flow_imp.id(38532784373886544419)
,p_name=>'Failed Details'
,p_static_id=>'failed-details'
,p_title=>'Details'
,p_parent_plug_id=>wwv_flow_imp.id(38532783448999544410)
,p_template=>4073835273271169698
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-AVPList--fixedLabelLarge:t-AVPList--leftAligned'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    -- DETAIL ',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].id''), ''-'') AS PAYMENT_ID,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].amount'') / 100,0) AS AMOUNT,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].currency''), ''-'') AS CURRENCY,',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].status''), ''-'')) AS PAYMENT_STATUS,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].order_id''),''-'') AS ORDER_ID,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].invoice_id''),''-'') AS INVOICE_ID,',
'',
'    --- ERROR',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_code''),''-'') AS ERROR_CODE,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_source''),''-'') AS ERROR_SOURCE,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_step''),''-'') AS ERROR_STEP,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_reason''),''-'') AS ERROR_REASON,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_description''),''-'') AS ERROR_DESCRIPTION,',
'',
'    -- PAYMENT METHOD',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].method''),''-'')) AS METHOD,',
'',
'    -- BANKING PAYMENT',
'    UPPER(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].bank''),''-'')) AS BANK,',
'',
'    -- CARD PAYMENT',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card_id''),''-'')) AS CARD_ID,',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card.id''),''-'')) AS CARD_CARD_ID,',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card.entity''),''-'')) AS CARD_ENTITY,',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card.name''),''-'')) AS CARD_NAME,',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card.last4''),''-'')) AS CARD_LAST4,',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card.network''),''-'')) AS CARD_NETWORK,',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card.type''),''-'')) AS CARD_TYPE,',
'    UPPER(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card.issuer''),''-'')) AS CARD_ISSUER,',
'    INITCAP(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].card.sub_type''),''-'')) AS CARD_SUB_TYPE,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].acquirer_data.auth_code''),''-'') AS CARD_AUTH_CODE,',
'',
'    -- FEES',
'',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].fee'') / 100,0) AS FEE,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].tax'') / 100,0) AS TAX,',
'',
'    -- Customer Details',
'    LOWER(NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].email''),''-'')) AS EMAIL,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].contact''),''-'') AS CONTACT,',
'',
'',
'    -- CREATED AT',
'    DATE ''1970-01-01'' + ( json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].created_at'') / 86400 ) AS CREATED_DATETIME',
'',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].id'') = :P25_RAZORPAY_PAYMENT_ID',
'AND PAYMENT_TYPE_ID = 1'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P25_RAZORPAY_PAYMENT_ID'
,p_lazy_loading=>false
,p_query_row_template=>2101991776017792140
,p_query_num_rows=>15
,p_query_options=>'DERIVED_REPORT_COLUMNS'
,p_csv_output=>'N'
,p_prn_output=>'N'
,p_sort_null=>'L'
,p_plug_query_strip_html=>'N'
,p_created_on=>wwv_flow_imp.dz('20260917044823Z')
,p_updated_on=>wwv_flow_imp.dz('20260917052550Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
