,p_display_sequence=>10
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_component_template_options=>'#DEFAULT#'
,p_display_point=>'SUB_REGIONS'
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].amount'') / 100,0) AS AMOUNT,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].status''),''N/A'') AS PAYMENT_STATUS,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_code''),''N/A'') AS ERROR_CODE,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_description''),''N/A'') AS ERROR_DESCRIPTION,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_source''),''N/A'') AS ERROR_SOURCE,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].error_reason''),''N/A'') AS ERROR_REASON,',
'    DATE ''1970-01-01''',
'      + ( json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].created_at'') / 86400 )AS CREATED_DATETIME',
'',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].id'') = :P25_RAZORPAY_PAYMENT_ID',
'AND PAYMENT_TYPE_ID = 1',
''))
,p_ajax_enabled=>'Y'
