 p_id=>wwv_flow_imp.id(38826020720382412836)
,p_name=>'Razor Pay Order'
,p_static_id=>'razor-pay-order'
,p_title=>'RazorPay Order Details'
,p_template=>4073835273271169698
,p_display_sequence=>20
,p_region_template_options=>'#DEFAULT#:t-Region--scrollBody'
,p_component_template_options=>'#DEFAULT#:t-AVPList--fixedLabelLarge:t-AVPList--leftAligned:t-Report--hideNoPagination'
,p_grid_column_span=>5
,p_display_column=>5
,p_source_type=>'NATIVE_SQL_REPORT'
,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.id''), ''N/A'')AS ORDER_ID,',
'     NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.items[0].id''),''-'') AS PAYMENT_ID,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.amount'') / 100, 0)AS AMOUNT,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.amount_paid'') / 100, 0)AS AMOUNT_PAID,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.amount_due'') / 100, 0)AS AMOUNT_DUE,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.currency''), ''N/A'')AS CURRENCY,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.receipt''), ''N/A'')AS RECEIPT,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.status''), ''N/A'')AS STATUS,',
'    NVL(json_value(R_ORDER_RESPONSE_JSON, ''$.attempts''), ''N/A'')AS ATTEMPTS,',
'    DATE ''1970-01-01''',
'      + ( json_value(R_ORDER_RESPONSE_JSON, ''$.created_at'') / 86400 )',
'        AS ORDER_CREATED_DATETIME',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE (json_value(R_ORDER_RESPONSE_JSON, ''$.id'')) = :P26_RAZORPAY_ORDER_ID',
'AND PAYMENT_TYPE_ID = 1',
'ORDER BY ORDER_CREATED_DATETIME DESC;'))
,p_ajax_enabled=>'Y'
,p_ajax_items_to_submit=>'P26_RAZORPAY_ORDER_ID'
,p_lazy_loading=>false
,p_query_row_template=>2101991776017792140
