 p_id=>wwv_flow_imp.id(38831870926835672638)
,p_event_id=>wwv_flow_imp.id(38831870644642672635)
,p_event_result=>'TRUE'
,p_action_sequence=>20
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    'var ordid   = $v(''P29_ORDERID'');',
    'var amount  = $v(''P29_TOTAL_AMOUNT'');',
    'var name    = $v(''P29_USER_NAME'');',
    'var email   = $v(''P29_USER_EMAIL'');',
    'var mobile  = $v(''P29_USER_MOBILE'');',
    '',
    'var options = {',
    '  key: "rzp_test_RD6JUoeu30e1cx",',
    '  amount: amount,           ',
    '  currency: "INR",',
    '  name: "Tavish Infotech",',
    '  description: "Order Payment",',
    '  image: "https://tavishinfotech.com/assets/tavish-new-logo.svg",',
    '  order_id: ordid,',
    '',
    '  /* ===== PAYMENT SUCCESS ===== */',
    ' handler: function (response) {',
    '',
    '    apex.server.process(',
    '      "SAVE_RAZORPAY_SUCCESS",',
    '      {',
    '        x01: response.razorpay_payment_id,',
    '        x02: response.razorpay_order_id,',
    '        x03: response.razorpay_signature',
    '      },',
    '      {',
    '        success: function () {',
    '          var url = "f?p=&APP_ID.:24:&APP_SESSION.";',
    '          apex.navigation.redirect(url);',
    '        },',
    '        error: function (err) {',
    '          console.error("AJAX Error:", err);',
    '          alert("Payment succeeded but saving data failed.");',
    '        }',
    '      }',
    '    );',
    '  },',
    '',
    '  /* ===== PREFILL USER DETAILS ===== */',
    '  prefill: {',
    '    name: name,',
    '    email: email,',
    '    contact: mobile',
    '  },',
    '',
    '  theme: {',
    '    color: "#F37254"',
    '  },',
    '',
    '  /* ===== USER CLOSES PAYMENT POPUP ===== */',
    '  modal: {',
    '    ondismiss: function () {',
    '',
    '      var targetPage = 23;',
    '',
    '      var url =',
    '        "f?p=&APP_ID.:" +',
    '        targetPage +',
    '        ":&APP_SESSION.::NO::" +',
    '        "P23_ORDER_ID:" +',
    '        encodeURIComponent(ordid);',
    '',
    '      apex.navigation.redirect(url);',
    '    }',
    '  }',
    '};',
    '',
    '/* ===== CREATE RAZORPAY INSTANCE ===== */',
    'var rzp1 = new Razorpay(options);',
    '',
    '/* ===== PAYMENT FAILED ===== */',
    'rzp1.on(''payment.failed'', function (response) {',
    '',
    '  var targetPage = 23;',
    '',
    '  var url =',
    '    "f?p=&APP_ID.:" +',
    '    targetPage +',
    '    ":&APP_SESSION.::NO::" +',
    '    "P23_ORDER_ID:" +',
    '    encodeURIComponent(ordid);',
    '',
    '  apex.navigation.redirect(url);',
    '});',
    '',
    '/* ===== OPEN PAYMENT POPUP ===== */',
    'rzp1.open();',
    '')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260917060546Z')
,p_updated_on=>wwv_flow_imp.dz('20260917061825Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
