wwv_flow_imp_page.create_page_da_action(
 p_id=>wwv_flow_imp.id(38844420048200751519)
,p_event_id=>wwv_flow_imp.id(38844419957207751518)
,p_event_result=>'TRUE'
,p_action_sequence=>10
,p_execute_on_page_init=>'N'
,p_static_id=>'native-javascript-code'
,p_action=>'NATIVE_JAVASCRIPT_CODE'
,p_attributes=>wwv_flow_t_plugin_attributes(wwv_flow_t_varchar2(
  'js_code', wwv_flow_string.join(wwv_flow_t_varchar2(
    '// Capture the Order Total in a JS Variable.',
    'var cartTotal = $v("P30_TOTAL_AMOUNT");',
    '',
    'const paypalButtonsComponent = paypal.Buttons({',
    '  // optional styling for buttons',
    '  style: {',
    '    color: "gold",',
    '    shape: "pill",',
    '    layout: "vertical"',
    '  },',
    '',
    '  // Prepare the PayPal transaction with the Order Total',
    '  createOrder: (data, actions) => {',
    '      const createOrderPayload = {',
    '          purchase_units: [',
    '              {',
    '                  amount: {',
    '                    // currency_code: "INR",',
    '                      value: cartTotal',
    '                    //   currency_code: ''INR''',
    '                  }',
    '              }',
    '          ]',
    '      };',
    '      return actions.order.create(createOrderPayload);',
    '  },',
    '',
    '  // finalize the transaction, called when user completes payment.',
    '  onApprove: (data, actions) => {',
    '      const captureOrderHandler = (details) => {',
    '      const payerName = details.payer.name.given_name;',
    '      // Store the PayPal JSON Response in an APEX Page Item.',
    '      $s("P30_PAYPAL_RESPONSE_JSON", JSON.stringify(details, null, 2));',
    '      };',
    '      return actions.order.capture().then(captureOrderHandler);',
    '  },',
    '',
    '  // handle unrecoverable errors',
    '  onError: (err) => {',
    '    // Additional Code required here to handle errors from PayPal.',
    '    console.error(''An error prevented the buyer from checking out with PayPal'');',
    '  }',
    '  });',
    '',
    '  // Cause PayPal buttons to be rendered.',
    '  paypalButtonsComponent',
    '      .render("#paypal-button-container")',
    '      .catch((err) => {',
    '        // Additional Code required here to handle errors rendering PayPal Buttons.',
    '        console.error(''PayPal Buttons failed to render'');',
    '});',
    '')))).to_clob
,p_created_on=>wwv_flow_imp.dz('20260917064618Z')
,p_updated_on=>wwv_flow_imp.dz('20260917064618Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
