'    NVL(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.name''), ''-'')AS CUSTOMER_NAME,',
'',
'    DATE ''1970-01-01''',
'      + ( json_value(S_SESSION_RESPONSE_JSON, ''$.created'') / 86400 )',
'        AS CREATED_DATETIME',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE (json_value(S_SESSION_RESPONSE_JSON, ''$.id'')) IS NOT NULL',
