,p_query_type=>'SQL'
,p_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    NVL(LOWER(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.email'')), ''-'')AS CUSTOMER_EMAIL,',
'    NVL(INITCAP(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.name'')), ''-'')AS CUSTOMER_NAME,',
'    NVL(INITCAP(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.address.city'')), ''-'') AS CITY,',
'    NVL(INITCAP(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.address.country'')), ''-'') AS COUNTYR,',
'    NVL(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.address.line1''), ''-'') AS LINE1,',
'    NVL(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.address.line2''), ''-'') AS LINE2,',
'    NVL(json_value(S_SESSION_RESPONSE_JSON, ''$.customer_details.address.postal_code''), ''-'') AS POSTAL_CODE,',
