wwv_flow_imp_page.create_page_plug(
 p_id=>wwv_flow_imp.id(38844422406133751543)
,p_plug_name=>'Payment Amount Detail'
,p_static_id=>'payment-amount-detail'
,p_region_name=>'success_payment_amount'
,p_parent_plug_id=>wwv_flow_imp.id(38844422377892751542)
,p_region_template_options=>'#DEFAULT#:t-CardsRegion--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2074200852440250129
,p_plug_display_sequence=>10
,p_plug_display_point=>'SUB_REGIONS'
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    NVL(TO_CHAR(json_value(PAYMENT_RESPONSE_JSON, ''$.amount'') / 100, ''999G999G999G999G990D00''), 0) AS AMOUNT,',
'    NVL(UPPER(json_value(PAYMENT_RESPONSE_JSON, ''$.currency'')), ''-'')AS CURRENCY,',
'    CASE',
'        WHEN json_value(PAYMENT_RESPONSE_JSON, ''$.status'') = ''requires_source'' THEN ''Incompleted''',
'        ELSE INITCAP(json_value(PAYMENT_RESPONSE_JSON, ''$.status''))',
'    END AS PAYMENT_STATUS,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.id''), ''N/A'')AS PAYMENT_ID,',
'    NVL(INITCAP(json_value(PAYMENT_RESPONSE_JSON, ''$.payment_method_types[*]'')), ''-'')AS METHOD,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.charges.data[0].billing_details.email''), ''-'')AS CUSTOMER_EMAIL,',
'    NVL(json_value(PAYMENT_RESPONSE_JSON, ''$.charges.data[0].billing_details.name''), ''-'')AS CUSTOMER_NAME,',
'    DATE ''1970-01-01''',
'      + ( json_value(PAYMENT_RESPONSE_JSON, ''$.created'') / 86400 )',
'        AS CREATED_DATETIME',
'FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE (json_value(PAYMENT_RESPONSE_JSON, ''$.id'')) = :P32_STRIPE_PAYMENT_ID',
'AND PAYMENT_TYPE_ID = 2'))
,p_lazy_loading=>false
,p_plug_source_type=>'NATIVE_CARDS'
,p_plug_query_num_rows_type=>'SCROLL'
,p_show_total_row_count=>false
,p_created_on=>wwv_flow_imp.dz('20260917091414Z')
,p_updated_on=>wwv_flow_imp.dz('20260917091415Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
