wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(38871104341864942320)
,p_computation_sequence=>10
,p_computation_item=>'P32_ALLOWED_PAYMENT_METHODS'
,p_static_id=>'p32-allowed-payment-methods'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT LISTAGG(initcap(jt.allowed_source_type), '', '')',
'         WITHIN GROUP (ORDER BY jt.allowed_source_type) AS allowed_source_types',
'FROM XXPI_PAYMENT_RESPONSE_HIST t',
'CROSS JOIN JSON_TABLE(',
'  t.PAYMENT_RESPONSE_JSON,',
'  ''$.allowed_source_types[*]''',
'  COLUMNS (',
'    allowed_source_type VARCHAR2(50) PATH ''$''',
'  )',
') jt',
'WHERE json_value(PAYMENT_RESPONSE_JSON, ''$.id'') = :P32_STRIPE_PAYMENT_ID',
'AND PAYMENT_TYPE_ID = 2;'))
,p_created_on=>wwv_flow_imp.dz('20260917091414Z')
,p_updated_on=>wwv_flow_imp.dz('20260917091414Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
wwv_flow_imp_page.create_page_computation(
 p_id=>wwv_flow_imp.id(38844422043936751539)
,p_computation_sequence=>10
,p_computation_item=>'P32_STRIPE_PAYMENT_RESPONSE'
,p_static_id=>'p32-stripe-payment-response'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'QUERY'
,p_computation=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT PAYMENT_RESPONSE_JSON FROM XXPI_PAYMENT_RESPONSE_HIST',
'WHERE json_value(PAYMENT_RESPONSE_JSON, ''$.id'') = :P32_STRIPE_PAYMENT_ID',
'AND PAYMENT_TYPE_ID = 2'))
,p_created_on=>wwv_flow_imp.dz('20260917091414Z')
,p_updated_on=>wwv_flow_imp.dz('20260917091414Z')
,p_created_by=>'ARCHIPATEL2632004@GMAIL.COM'
,p_updated_by=>'ARCHIPATEL2632004@GMAIL.COM'
);
