 p_id=>wwv_flow_imp.id(38871104056406942317)
,p_computation_sequence=>10
,p_computation_item=>'P32_SUCCESS_PAYMENT_EXCHANGE_RATE'
,p_static_id=>'p32-success-payment-exchange-rate'
,p_computation_point=>'BEFORE_HEADER'
,p_computation_type=>'QUERY'
